    Bug 1968967 - Don't trigger item selection on double clicks and only handle single click. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D257086

diff --git a/mail/base/content/widgets/tree-view.mjs b/mail/base/content/widgets/tree-view.mjs
index 55bcea98a60..513467af1ee 100644
--- a/mail/base/content/widgets/tree-view.mjs
+++ b/mail/base/content/widgets/tree-view.mjs
@@ -307,7 +307,10 @@ export class TreeView extends HTMLElement {
         break;
       }
       case "click": {
-        if (event.button !== 0) {
+        // Bail out on non primary or double clicks.
+        if (event.button !== 0 || event.detail !== 1) {
+          // Ensure the focus is not moved somewhere else.
+          this.ensureCorrectFocus();
           return;
         }

